const toolDir=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..'),repoRoot=path.resolve(toolDir,'../..');
const load=relative=>JSON.parse(fs.readFileSync(path.join(repoRoot,relative),'utf8'));
const run=()=>spawnSync(process.execPath,['check-stateful.mjs'],{cwd:toolDir,encoding:'utf8'});
const canonical=(origin_log,identity)=>({ref_type:'CANONICAL',origin_log,identity});
const decision=(event_id,object_refs)=>({event_type:'HUMAN_DECISION',event_id,actor_ref:'opaque-actor',scope_ref:'opaque-scope',object_refs,occurred_at:'2026-11-07T12:00:00Z',recorded_at:'2026-11-07T12:00:01Z'});
const omissionOperation=(event,event_id,state,overrides={})=>({operation:'APPEND',log:'AUDIT_LOG',record:{identity:event_id,payload:{...structuredClone(state.preconditions.e_minus_proofs[0]?.candidate??{}),...structuredClone(event),...structuredClone(overrides),event_id}}});
const ownAccessor=(key,kind,counter)=>{const value={};Object.defineProperty(value,key,{enumerable:true,configurable:true,[kind](){counter.count++;return kind==='get'?[]:undefined;}});return value;};
const prototypeSafetyScenario=()=>({scenario_id:'prototype-safety',classification:'NEGATIVE',requirement_ids:[],steps:[{operation:{operation:'DELETE',log:'MANAGEMENT_LOG',identity:'prototype-safe'},expected:{accepted:false,code:'FORBIDDEN_MUTATION',history_delta:0,before_equals_after:true}}]});
const demotedProjectionIds=['JN-CORE-0_2-REQ-L019-A01','JN-CORE-0_2-REQ-D025','JN-CORE-0_2-REQ-D076','JN-CORE-0_2-REQ-D077','JN-CORE-0_2-REQ-D079'];

test('Object.prototype contamination never executes inherited getters',()=>{for(const key of ['expectations','operation','foundation_profile','preconditions','toJSON']){const previous=Object.getOwnPropertyDescriptor(Object.prototype,key),counter={count:0};if(previous&&!previous.configurable)throw new Error('Required temporary prototype property is not configurable');try{Object.defineProperty(Object.prototype,key,{configurable:true,get(){counter.count++;throw new Error('INHERITED_GETTER_EXECUTED');}});const state=createState();const rejected=applyOperation(state,{operation:'DELETE',log:'MANAGEMENT_LOG',identity:'prototype-safe'});assert.equal(rejected.code,'FORBIDDEN_MUTATION');assert.doesNotThrow(()=>historyHash(state));assert.equal(runScenario(prototypeSafetyScenario()).rejected_steps,1);assert.equal(counter.count,0);}finally{if(previous)Object.defineProperty(Object.prototype,key,previous);else delete Object.prototype[key];}assert.equal(counter.count,0);}});
test('normalized states and structured descendants have null prototypes',()=>{const state=createState({reference_aliases:[{alias:'alias',target:canonical('MANAGEMENT_LOG','target')}]}),rejected=applyOperation(state,{operation:'DELETE',log:'MANAGEMENT_LOG',identity:'target'}),accepted=applyOperation(state,{operation:'APPEND',log:'MANAGEMENT_LOG',record:{identity:'target',payload:{nested:{valid:true}}}});for(const value of [state,state.logs,state.preconditions,state.preconditions.reference_aliases[0],state.preconditions.reference_aliases[0].target,rejected.next_state,rejected.next_state.logs,accepted.next_state,accepted.next_state.logs,accepted.next_state.logs.MANAGEMENT_LOG[0],accepted.next_state.logs.MANAGEMENT_LOG[0].payload,accepted.next_state.logs.MANAGEMENT_LOG[0].payload.nested])assert.equal(Object.getPrototypeOf(value),null);assert.equal(Object.getPrototypeOf(state.logs.MANAGEMENT_LOG),Array.prototype);assert.doesNotThrow(()=>historyHash(rejected.next_state));assert.doesNotThrow(()=>historyHash(accepted.next_state));});
test('safe serializer preserves golden bytes hashes codes and deltas',()=>{assert.equal(stable({b:1,a:[true,'x',null]}),'{"a":[true,"x",null],"b":1}\n');const state=createState(),rejected=applyOperation(state,{operation:'DELETE',log:'MANAGEMENT_LOG',identity:'golden'}),accepted=applyOperation(state,{operation:'APPEND',log:'MANAGEMENT_LOG',record:{identity:'golden',payload:{nested:{valid:true}}}});assert.equal(historyHash(state),'fa559bd86cecbc386e1c6af0bf84a1c85eae8e6f19fb5d9ff6ec9d43f10f32c7');assert.deepEqual([rejected.code,rejected.before_hash,rejected.after_hash,rejected.history_delta],['FORBIDDEN_MUTATION','fa559bd86cecbc386e1c6af0bf84a1c85eae8e6f19fb5d9ff6ec9d43f10f32c7','fa559bd86cecbc386e1c6af0bf84a1c85eae8e6f19fb5d9ff6ec9d43f10f32c7',0]);assert.deepEqual([accepted.code,accepted.before_hash,accepted.after_hash,accepted.history_delta],['APPENDED','fa559bd86cecbc386e1c6af0bf84a1c85eae8e6f19fb5d9ff6ec9d43f10f32c7','4d13129b259af7614073786e46cbee2c4513862a5e24aca19cab8aa4aa973af8',1]);});

test('data-only preconditions reject own and inherited accessors without execution',()=>{for(const kind of ['get','set']){const counter={count:0};assert.throws(()=>createState(ownAccessor('expectations',kind,counter)),/INVALID_PRECONDITIONS_DATA/);assert.equal(counter.count,0);}const counter={count:0},prototype=ownAccessor('inherited','get',counter),input=Object.create(prototype);Object.defineProperty(input,'expectations',{value:[],enumerable:true});assert.throws(()=>createState(input),/INVALID_PRECONDITIONS_DATA/);assert.equal(counter.count,0);});
test('data-only operation and context reject accessors without execution',()=>{const state=createState();for(const [target,key] of [['operation','operation'],['context','channel']]){const counter={count:0},hostile=ownAccessor(key,'get',counter);assert.throws(()=>target==='operation'?applyOperation(state,hostile,{}):applyOperation(state,{operation:'APPEND',log:'MANAGEMENT_LOG',record:{identity:'safe',payload:{}}},hostile),new RegExp(target==='operation'?'INVALID_OPERATION_DATA':'INVALID_CONTEXT_DATA'));assert.equal(counter.count,0);}});
test('Proxy traps are rejected before reflection and never execute',()=>{for(const trap of ['get','ownKeys','getOwnPropertyDescriptor','getPrototypeOf']){const counter={count:0},proxy=new Proxy({}, {[trap](){counter.count++;throw new Error('trap executed');}});assert.throws(()=>createState(proxy),/INVALID_PRECONDITIONS_DATA/);assert.equal(counter.count,0);}});
test('untrusted and proxied states fail closed before reads or hashing',()=>{const operation={operation:'APPEND',log:'MANAGEMENT_LOG',record:{identity:'safe',payload:{}}},handcrafted={logs:{MANAGEMENT_LOG:[],SCHEMA_LOG:[],AUDIT_LOG:[]},preconditions:{}},state=createState(),counter={count:0},proxied=new Proxy(state,{get(){counter.count++;throw new Error('trap executed');}});assert.throws(()=>applyOperation(handcrafted,operation),/UNTRUSTED_STATE/);assert.throws(()=>historyHash(handcrafted),/UNTRUSTED_STATE/);assert.throws(()=>applyOperation(proxied,operation),/UNTRUSTED_STATE/);assert.throws(()=>historyHash(proxied),/UNTRUSTED_STATE/);assert.equal(counter.count,0);});
test('functions symbols undefined bigint nonfinite numbers and cycles are rejected',()=>{for(const hostile of [()=>true,Symbol('hostile'),undefined,1n,NaN,Infinity,-Infinity])assert.throws(()=>createState({expectations:[hostile]}),/INVALID_PRECONDITIONS_DATA/);const cycle={};cycle.self=cycle;assert.throws(()=>createState(cycle),/INVALID_PRECONDITIONS_DATA/);const symbolKey={};Object.defineProperty(symbolKey,Symbol('key'),{value:'hostile',enumerable:true});assert.throws(()=>createState(symbolKey),/INVALID_PRECONDITIONS_DATA/);});
test('runScenario rejects hostile inputs before access or materialization',()=>{const counter={count:0},scenario=ownAccessor('steps','get',counter);assert.throws(()=>runScenario(scenario),/INVALID_SCENARIO_DATA/);assert.equal(counter.count,0);const proxyCounter={count:0},proxy=new Proxy({},{ownKeys(){proxyCounter.count++;throw new Error('trap executed');}});assert.throws(()=>runScenario(proxy),/INVALID_SCENARIO_DATA/);assert.equal(proxyCounter.count,0);});
test('valid JSON behavior returns deeply frozen branded states',()=>{const state=createState(),rejected=applyOperation(state,{operation:'DELETE',log:'MANAGEMENT_LOG',identity:'retry'}),accepted=applyOperation(state,{operation:'APPEND',log:'MANAGEMENT_LOG',record:{identity:'retry',payload:{nested:{valid:true}}}});for(const next of [state,rejected.next_state,accepted.next_state]){assert.doesNotThrow(()=>historyHash(next));assert.ok(Object.isFrozen(next));assert.ok(Object.isFrozen(next.logs));assert.ok(Object.isFrozen(next.preconditions));}assert.equal(rejected.history_delta,0);assert.equal(rejected.before_hash,rejected.after_hash);assert.equal(accepted.accepted,true);});

test('manifest and cases are reciprocal and every scenario is deterministic',()=>{const manifest=load('conformance/core-lite-v0.2/scenarios/manifest.json'),cases=load('conformance/core-lite-v0.2/scenarios/history-reference.cases.json');const first=validateScenarioBundle(manifest,cases),second=validateScenarioBundle(manifest,cases);assert.deepEqual(first,second);assert.equal(first.length,cases.scenario_count);});
test('scenario and catalog traceability is exact reciprocal and polarity-correct',()=>{const cases=load('conformance/core-lite-v0.2/scenarios/history-reference.cases.json'),{catalog}=validateCatalog();for(const scenario of cases.scenarios){const expected=catalog.requirements.filter(requirement=>[...requirement.stateful_positive_scenario_refs,...requirement.stateful_negative_scenario_refs].includes(scenario.scenario_id)).map(requirement=>requirement.requirement_id);assert.deepEqual(scenario.requirement_ids,expected);for(const requirement of catalog.requirements.filter(item=>item.stateful_positive_scenario_refs.includes(scenario.scenario_id)))assert.match(scenario.classification,/POSITIVE/);for(const requirement of catalog.requirements.filter(item=>item.stateful_negative_scenario_refs.includes(scenario.scenario_id)))assert.match(scenario.classification,/NEGATIVE/);}});
test('semantic attribution is subject and rejection-cause correct',()=>{const{catalog}=validateCatalog(),get=id=>catalog.requirements.find(item=>item.requirement_id===id);assert.deepEqual(get('JN-CORE-0_2-REQ-L013-A01').stateful_positive_scenario_refs,['resolve-prior-object-reference']);assert.deepEqual(get('JN-CORE-0_2-REQ-L013-A01').stateful_negative_scenario_refs,['reject-unresolved-reference']);assert.deepEqual(get('JN-CORE-0_2-REQ-L014-A01').stateful_negative_scenario_refs,['reject-audit-writer-unresolved-reference']);assert.deepEqual(get('JN-CORE-0_2-REQ-L015-A01').stateful_negative_scenario_refs,['reject-unauthorized-audit-writer']);assert.deepEqual(get('JN-CORE-0_2-REQ-L016-A01').stateful_negative_scenario_refs,['reject-direct-audit-writer-bypass']);assert.deepEqual(get('JN-CORE-0_2-REQ-D042').stateful_positive_scenario_refs,['resolve-prior-object-reference']);assert.deepEqual(get('JN-CORE-0_2-REQ-D055').stateful_negative_scenario_refs,['reject-audit-writer-self-reference']);assert.deepEqual(get('JN-CORE-0_2-REQ-D058').stateful_positive_scenario_refs,[]);assert.deepEqual(get('JN-CORE-0_2-REQ-D058').stateful_negative_scenario_refs,[]);assert.deepEqual(get('JN-CORE-0_2-REQ-D106').stateful_negative_scenario_refs,['reject-audit-event-identity-event-id-mismatch']);const cases=load('conformance/core-lite-v0.2/scenarios/history-reference.cases.json'),origin=cases.scenarios.find(item=>item.scenario_id==='reject-automatic-human-decision-origin');assert.deepEqual(origin.requirement_ids,[]);assert.deepEqual(origin.excluded_requirement_ids,['JN-CORE-0_2-REQ-L011-A01','JN-CORE-0_2-REQ-D105']);for(const id of ['resolve-prior-object-reference','reject-unresolved-reference','reject-audit-writer-unresolved-reference','reject-wrong-origin-log','reject-audit-writer-self-reference']){const scenario=cases.scenarios.find(item=>item.scenario_id===id);assert.ok(scenario.steps.some(step=>step.operation.record?.payload?.event_type==='HUMAN_DECISION'));}});
test('applyOperation is functional and rejection does not mutate or reserve',()=>{const state=createState(),operation={operation:'CHECK_OBJECT_REFS',origin_log:'MANAGEMENT_LOG',identity:'opaque-retry',object_refs:[canonical('MANAGEMENT_LOG','missing')]},context={};const beforeState=structuredClone(state),beforeOperation=structuredClone(operation),beforeContext=structuredClone(context),rejected=applyOperation(state,operation,context);assert.equal(stable(state),stable(beforeState));assert.deepEqual(operation,beforeOperation);assert.deepEqual(context,beforeContext);assert.equal(rejected.accepted,false);assert.equal(rejected.before_hash,rejected.after_hash);const accepted=applyOperation(state,{operation:'APPEND',log:'MANAGEMENT_LOG',record:{identity:'opaque-retry',payload:{}}});assert.equal(accepted.accepted,true);assert.equal(stable(state),stable(beforeState));assert.notEqual(accepted.next_state,state);assert.equal(accepted.next_state.logs.MANAGEMENT_LOG.length,1);});
test('state preconditions aliases and exposed histories are deeply frozen',()=>{const suppliedWriters=['writer-tech'],suppliedAliases=[{alias:'target-alias',target:canonical('MANAGEMENT_LOG','target')}],state=createState({authorized_audit_writer_refs:suppliedWriters,reference_aliases:suppliedAliases}),before=historyHash(state);assert.ok(Object.isFrozen(state));assert.ok(Object.isFrozen(state.logs));assert.ok(Object.isFrozen(state.logs.AUDIT_LOG));assert.ok(Object.isFrozen(state.preconditions));assert.ok(Object.isFrozen(state.preconditions.authorized_audit_writer_refs));assert.ok(Object.isFrozen(state.preconditions.reference_aliases));assert.ok(Object.isFrozen(state.preconditions.reference_aliases[0].target));assert.throws(()=>state.preconditions.authorized_audit_writer_refs.push('injected'));assert.throws(()=>{state.preconditions.authorized_audit_writer_refs=['injected'];});assert.throws(()=>{state.preconditions.reference_aliases[0].target.identity='changed';});assert.throws(()=>state.logs.AUDIT_LOG.push({identity:'injected'}));assert.equal(historyHash(state),before);suppliedWriters.push('external-injected');suppliedAliases[0].target.identity='external-changed';assert.equal(historyHash(state),before);const candidate={operation:'APPEND',log:'AUDIT_LOG',record:{identity:'external-event',payload:{event_type:'AUDIT_EVENT',event_id:'external-event'}}};assert.equal(applyOperation(state,candidate,{channel:'AUDIT_WRITER',writer_ref:'external-injected'}).code,'AUDIT_WRITER_NOT_AUTHORIZED');const accepted=applyOperation(state,{operation:'APPEND',log:'MANAGEMENT_LOG',record:{identity:'target',payload:{}}});assert.ok(Object.isFrozen(accepted.next_state));assert.ok(Object.isFrozen(accepted.next_state.logs.MANAGEMENT_LOG));});
test('E-minus inputs and derived proofs are cloned deeply frozen and caller overrides are rejected',()=>{const cases=load('conformance/core-lite-v0.2/scenarios/history-reference.cases.json'),supplied=structuredClone(cases.omission_foundation_preconditions),state=createState(supplied),before=historyHash(state);for(const key of ['constitutive_evaluations','evidence_artifacts','e_minus_proofs']){assert.ok(Object.isFrozen(state.preconditions[key]));assert.ok(Object.isFrozen(state.preconditions[key][0]));}supplied.constitutive_evaluations[0].expectations[0].version='external-change';assert.equal(historyHash(state),before);assert.throws(()=>{state.preconditions.e_minus_proofs[0].proof.replay_digest='changed';});const operation=omissionOperation(cases.omission_foundation_event,'override-operation',state);operation.constitutive_evaluations=[];assert.equal(applyOperation(state,operation,{channel:'AUDIT_WRITER',writer_ref:'writer-tech-1'}).code,'OPERATION_PRECONDITION_OVERRIDE_FORBIDDEN');assert.equal(applyOperation(state,omissionOperation(cases.omission_foundation_event,'override-context',state),{channel:'AUDIT_WRITER',writer_ref:'writer-tech-1',constitutive_evaluations:[]}).code,'CONTEXT_PRECONDITION_OVERRIDE_FORBIDDEN');assert.throws(()=>createState({observations:[]}),/LEGACY_E_MINUS_ORACLE_INPUT_FORBIDDEN/);});
test('constitutive inputs are data-only and versioned registries resolve exact pairs',()=>{const cases=load('conformance/core-lite-v0.2/scenarios/history-reference.cases.json'),context={channel:'AUDIT_WRITER',writer_ref:'writer-tech-1'};let state=createState(cases.omission_foundation_preconditions),operation=omissionOperation(cases.omission_foundation_event,'data-only',state);operation.caller_evaluator=()=>true;assert.throws(()=>applyOperation(state,operation,context),/INVALID_OPERATION_DATA/);assert.throws(()=>applyOperation(state,omissionOperation(cases.omission_foundation_event,'clock',state),{...context,external_clock:()=>0}),/INVALID_CONTEXT_DATA/);const versioned=structuredClone(cases.omission_foundation_preconditions),input=versioned.constitutive_evaluations[0];input.expectations.unshift({...input.expectations[0],version:'v0'});input.procedures.unshift({...input.procedures[0],version:'v0'});versioned.evidence_artifacts.unshift({...versioned.evidence_artifacts[0],version:'v0'});versioned.evidence_artifacts.find(item=>item.version==='v1').digest=evaluateConstitutiveEMinus(input).proof.observation_digest;state=createState(versioned);assert.equal(applyOperation(state,omissionOperation(cases.omission_foundation_event,'exact-version',state),context).accepted,true);const ambiguous=structuredClone(versioned),ambiguousInput=ambiguous.constitutive_evaluations[0];ambiguousInput.expectations.push(structuredClone(ambiguousInput.expectations.find(item=>item.version==='v1')));state=createState(ambiguous);assert.equal(applyOperation(state,omissionOperation(cases.omission_foundation_event,'ambiguous-version',state),context).code,'EXPECTATION_VERSION_AMBIGUOUS');});
test('temporal applicability and deterministic source-local windows are derived',()=>{const cases=load('conformance/core-lite-v0.2/scenarios/history-reference.cases.json'),context={channel:'AUDIT_WRITER',writer_ref:'writer-tech-1'},probe=preconditions=>{const state=createState(preconditions);return applyOperation(state,omissionOperation(cases.omission_foundation_event,'temporal-probe',state),context);};const noTemporal=structuredClone(cases.omission_foundation_preconditions);noTemporal.constitutive_evaluations[0].expectations[0].temporal_applicability={};assert.equal(probe(noTemporal).code,'EXPECTATION_QUALIFICATION_INCOMPLETE');const outside=structuredClone(cases.omission_foundation_preconditions);outside.constitutive_evaluations[0].expectations[0].temporal_applicability.through_ordinal=30;assert.equal(probe(outside).code,'EXPECTATION_NOT_APPLICABLE_AT_CUTOFF');const noWindow=structuredClone(cases.omission_foundation_preconditions);noWindow.constitutive_evaluations[0].scopes[0].sources[0].window={};assert.equal(probe(noWindow).code,'SCOPE_INCOMPLETE');});
test('Audit Writer integration consumes cutoff-bounded candidate and evidence digest',()=>{const cases=load('conformance/core-lite-v0.2/scenarios/history-reference.cases.json'),context={channel:'AUDIT_WRITER',writer_ref:'writer-tech-1'},base=createState(cases.omission_foundation_preconditions),future=structuredClone(cases.omission_foundation_preconditions),input=future.constitutive_evaluations[0],source=input.snapshot.sources[0];source.complete_through_ordinal=500;source.records.push({identity:'noise-1',ordinal:46,subject_ref:'subject-1',fields:{record_kind:'expected-kind'}},{identity:'future-duplicate-ordinal',ordinal:45,subject_ref:'subject-1',fields:{record_kind:'expected-kind'}});const futureSchema={schema_context_ref:'schema-context-1',version:'v2',source_ref:'MANAGEMENT_LOG',applicable_from_ordinal:41,applicable_through_ordinal:100};futureSchema.digest=digestEvaluationData(futureSchema);input.schema_history.push(futureSchema);const state=createState(future),baseProof=base.preconditions.e_minus_proofs[0],futureProof=state.preconditions.e_minus_proofs[0];assert.equal(stable(futureProof),stable(baseProof));assert.equal(futureProof.proof.observation_digest,future.evidence_artifacts[0].digest);const before=historyHash(state),accepted=applyOperation(state,omissionOperation(cases.omission_foundation_event,'cutoff-bounded-integration',state),context);assert.equal(accepted.accepted,true);assert.equal(accepted.code,'APPENDED');assert.equal(accepted.next_state.logs.AUDIT_LOG[0].payload.evidence_refs[0].digest,future.evidence_artifacts[0].digest);assert.equal(historyHash(state),before);assert.equal(state.logs.AUDIT_LOG.length,0);});
