test('exact stateful completion and projection allowlists are preserved',()=>{const{catalog}=validateCatalog();assert.equal(statefulCoverageIds.length,39);assert.equal(statefulProjectionIds.length,7);assert.deepEqual(statefulProjectionIds.slice(-5),demotedProjectionIds);for(const id of statefulCoverageIds){const requirement=catalog.requirements.find(item=>item.requirement_id===id);assert.ok(requirement.coverage_markers.includes('STATEFUL_SCENARIO_COVERED'));assert.ok(requirement.coverage_markers.includes('REQUIREMENT_COMPLETE'));assert.equal(requirement.coverage_status.length,0);}for(const id of statefulProjectionIds){const requirement=catalog.requirements.find(item=>item.requirement_id===id);assert.deepEqual(requirement.coverage_markers,['STATEFUL_PROJECTION_COVERED']);assert.ok(requirement.coverage_status.length);}for(const id of demotedProjectionIds){const requirement=catalog.requirements.find(item=>item.requirement_id===id);assert.deepEqual(requirement.coverage_status,['MISSING_POSITIVE_FIXTURE','MISSING_NEGATIVE_FIXTURE','MISSING_TEST']);assert.deepEqual(requirement.test_refs,[]);assert.ok(requirement.stateful_positive_scenario_refs.length);assert.ok(requirement.stateful_negative_scenario_refs.length);assert.ok(requirement.stateful_test_refs.length);}const d080=catalog.requirements.find(item=>item.requirement_id==='JN-CORE-0_2-REQ-D080');assert.equal(d080.implementation_status,'NOT_IMPLEMENTED');assert.deepEqual(d080.stateful_positive_scenario_refs,[]);assert.deepEqual(d080.stateful_negative_scenario_refs,[]);});
test('check-stateful is byte-deterministic and does not claim conformance',()=>{const first=run(),second=run();assert.equal(first.status,0);assert.equal(second.status,0);assert.equal(first.stderr,'');assert.equal(second.stderr,'');assert.equal(first.stdout,second.stdout);const output=JSON.parse(first.stdout);assert.equal(output.scenario_count,60);assert.equal(output.scenario_runs_passed,60);assert.equal(output.stateful_complete_requirements,39);assert.equal(output.stateful_projection_requirements,7);assert.equal(output.technical_verdict,'NOT_EVALUATED');assert.equal(output.conformance_claimed,false);});
